struct Acc { std::mutex m; long bal = 100; };
void transfer(Acc& a, Acc& b, long n) {
  std::scoped_lock lk(a.m, b.m);
  a.bal -= n; b.bal += n;
}
int main() {
  Acc acc;
  std::cout << "start\n";
  transfer(acc, acc, 10);
  std::cout << "done " << acc.bal << '\n';
}

void transfer(Acc& a, Acc& b, long n) {
  if (&a == &b) return;  // nothing to move
  std::scoped_lock lk(a.m, b.m);
  a.bal -= n;
  b.bal += n;
}
